// Prepare Sources: turn the agent's raw tool results into clean, labelled sources,
// and check every report citation in the answer against the pages really retrieved.

const agent = $input.first().json;
const steps = agent.intermediateSteps || [];

const sourceTexts = [];   // clean text for the verifier
const validPages = [];    // report pages really retrieved, e.g. "Wipro|450"
const webSources = [];    // web results, kept for the UI and Langfuse

for (const step of steps) {
  // the tool result is usually JSON text, so turn it into a list
  let results = step.observation;
  if (typeof results === 'string') {
    try { results = JSON.parse(results); } catch (e) { continue; }
  }
  if (!Array.isArray(results)) results = [results];

  for (const r of results) {
    if (!r) continue;

    if (r.type === 'text') {
      // report search result: its text holds the page content and metadata
      let doc;
      try { doc = JSON.parse(r.text); } catch (e) { continue; }
      validPages.push(doc.metadata.company + '|' + doc.metadata.page);
      sourceTexts.push('[' + doc.metadata.company + ', page ' + doc.metadata.page + '] ' + doc.pageContent);

    } else if (r.source_page !== undefined) {
      // SQL row from verified_metrics
      validPages.push(r.company + '|' + r.source_page);
      sourceTexts.push('[' + r.company + ', page ' + r.source_page + '] ' + r.metric + ' = ' + r.value + ' ' + r.unit);

    } else if (r.link) {
      // web search result
      const site = r.source || r.link;
      const date = r.date ? ', ' + r.date : '';
      webSources.push({ title: r.title, link: r.link, source: site, date: r.date || '' });
      sourceTexts.push('[Web: ' + site + date + '] ' + r.title + ' - ' + (r.snippet || '') + ' (' + r.link + ')');
    }
  }
}

// find every report citation like "(Wipro, page 450)" in the answer
const answer = agent.output;
const pattern = /\((TCS|Infosys|Wipro), page (\d+)\)/g;
const citedPages = [];
let match;
while ((match = pattern.exec(answer)) !== null) {
  citedPages.push(match[1] + '|' + match[2]);
}

// a report citation is bad if its page was never retrieved
const badCitations = citedPages.filter(c => !validPages.includes(c));

return [{
  json: {
    answer: answer,
    sources: sourceTexts.join('\n\n'),
    cited_pages: citedPages,
    retrieved_pages: validPages,
    bad_citations: badCitations,
    citations_ok: badCitations.length === 0,
    web_sources: webSources
  }
}];

// Builds what we send to Langfuse:
// 1) the trace (question, answer, sources) in OpenTelemetry format - the new v4 way
// 2) the three scores - Langfuse keeps accepting scores after 16 Nov 2026

const sources = $('Prepare Sources').first().json;
const verifier = JSON.parse($('Answer Verifier').first().json.text);
const question = $('Chat Input').first().json.chatInput;
const sessionId = $('Chat Input').first().json.sessionId || 'no-session';

// random hex ids: a trace id is 32 characters, a span id is 16
function randomHex(length) {
  let text = '';
  for (let i = 0; i < length; i++) {
    text += Math.floor(Math.random() * 16).toString(16);
  }
  return text;
}
const traceId = randomHex(32);
const spanId = randomHex(16);

// time now in nanoseconds, as text (the number is too big for JavaScript)
const now = String(Date.now()) + '000000';

// tools the agent used
const steps = $('Research Agent').first().json.intermediateSteps || [];
const toolsUsed = steps.map(step => step.action.tool);

const shownToUser = verifier.confidence >= 0.7 && sources.citations_ok === true;

// one OpenTelemetry attribute
function attr(key, value) {
  return { key: key, value: { stringValue: String(value) } };
}

const otelBody = {
  resourceSpans: [{
    resource: { attributes: [attr('service.name', 'financial-research-agent')] },
    scopeSpans: [{
      scope: { name: 'n8n-prepare-langfuse-data' },
      spans: [{
        traceId: traceId,
        spanId: spanId,
        name: 'research-answer',
        kind: 1,
        startTimeUnixNano: now,
        endTimeUnixNano: now,
        attributes: [
          attr('langfuse.trace.name', 'financial-research-agent'),
          attr('langfuse.session.id', sessionId),
          attr('langfuse.trace.input', question),
          attr('langfuse.trace.output', sources.answer),
          attr('langfuse.observation.input', question),
          attr('langfuse.observation.output', sources.answer),
          attr('langfuse.trace.metadata.tools_used', JSON.stringify(toolsUsed)),
          attr('langfuse.trace.metadata.cited_pages', JSON.stringify(sources.cited_pages)),
          attr('langfuse.trace.metadata.bad_citations', JSON.stringify(sources.bad_citations)),
          attr('langfuse.trace.metadata.shown_to_user', shownToUser),
          attr('langfuse.trace.metadata.verifier_reason', verifier.reason),
          attr('langfuse.observation.metadata.sources', String(sources.sources).slice(0, 5000)),
        ],
      }],
    }],
  }],
};

// one score event
function score(name, value) {
  const id = name + '-' + traceId;
  return {
    id: id,
    type: 'score-create',
    timestamp: new Date().toISOString(),
    body: { id: id, traceId: traceId, name: name, value: value },
  };
}

const scoreBody = {
  batch: [
    score('verifier_confidence', verifier.confidence),
    score('supported', verifier.supported ? 1 : 0),
    score('citations_ok', sources.citations_ok ? 1 : 0),
  ],
};

return [{ json: { trace_id: traceId, otel_body: otelBody, score_body: scoreBody } }];
